"""Synthetische Szenen: graue Arena, zwei gleichfarbige Roboter mit verschiedener Form."""

import cv2
import numpy as np
import pytest

from hebocon.arena import Arena

W, H = 640, 480
CORNERS = [(100, 60), (540, 60), (560, 440), (80, 440)]
ROBOT_COLOR = (40, 40, 40)


def plate() -> np.ndarray:
    img = np.full((H, W, 3), 180, np.uint8)
    cv2.polylines(img, [np.array(CORNERS, np.int32)], True, (255, 255, 255), 3)
    return img


def draw_square(img: np.ndarray, center, size=50) -> None:
    x, y = int(center[0]), int(center[1])
    cv2.rectangle(img, (x - size // 2, y - size // 2), (x + size // 2, y + size // 2), ROBOT_COLOR, -1)


def draw_triangle(img: np.ndarray, center, size=70, angle=0.0) -> None:
    s = size // 2
    pts = np.array([[0, -s], [s, s], [-s, s]], np.float32)
    a = np.radians(angle)
    rot = np.array([[np.cos(a), np.sin(a)], [-np.sin(a), np.cos(a)]], np.float32)
    pts = pts @ rot + np.array(center, np.float32)
    cv2.fillPoly(img, [np.round(pts).astype(np.int32)], ROBOT_COLOR)


def scene(square=None, triangle=None, angle=0.0, hand=None) -> np.ndarray:
    img = plate()
    if square is not None:
        draw_square(img, square)
    if triangle is not None:
        draw_triangle(img, triangle, angle=angle)
    if hand is not None:
        # Hand als Rechteck in Roboterfarbe: der schlimmste Fall, Farbe hilft dem Tracker nicht.
        cv2.rectangle(img, hand[:2], hand[2:], ROBOT_COLOR, -1)
    return img


@pytest.fixture
def arena() -> Arena:
    a = Arena(np.array(CORNERS, np.float32))
    a.plate = plate()
    return a
